<script setup>
import {computed,onBeforeUnmount,ref,watch} from 'vue';
import axios from 'axios';
import {X,MessageSquare,Mail,Phone} from '@lucide/vue';
import MobileIdentityAvatar from './MobileIdentityAvatar.vue';
import {formatPhoneForDisplay} from '../utils/phoneDisplay.js';
const props=defineProps({apiBase:String,sessionToken:String,personId:[String,Number],agencyId:[String,Number]});
const emit=defineEmits(['close','message','compose-email']);
const person=ref(null),loading=ref(false),error=ref('');let request=0;
const phone=computed(()=>formatPhoneForDisplay(person.value?.workPhone,person.value?.workPhoneExtension));
async function load(){const current=++request;person.value=null;error.value='';if(!props.personId)return;loading.value=true;try{const{data}=await axios.get(`${props.apiBase}/directory/${props.personId}`,{headers:{'X-Quick-View-Session':props.sessionToken},withCredentials:true,params:{agencyId:props.agencyId}});if(current===request)person.value=data.person;}catch(e){if(current===request)error.value=e.response?.data?.error?.message||'This profile could not be opened.';}finally{if(current===request)loading.value=false;}}
function message(){emit('message',{id:person.value.id,name:person.value.displayName,agencyId:person.value.agencyId});}
watch(()=>[props.personId,props.agencyId,props.sessionToken],load,{immediate:true});onBeforeUnmount(()=>request++);
</script>
<template><Teleport to="body"><div class="person-profile-overlay" @click.self="emit('close')"><section role="dialog" aria-modal="true" aria-label="Person profile" @keydown.esc="emit('close')"><header><h2>Your people</h2><button aria-label="Close profile" @click="emit('close')"><X :size="20"/></button></header><p v-if="loading" role="status">Opening profile…</p><p v-if="error" role="alert">{{error}}</p><template v-if="person"><div class="person-heading"><MobileIdentityAvatar :photo="person.profilePhotoUrl" :agency-icon="person.agencyLogoUrl" :name="person.displayName"/><div><h3><span>{{person.displayName}}</span><span v-if="person.credential" class="credential">{{person.credential}}</span></h3><small v-if="person.isSchoolAdmin">SCHOOL ADMIN</small><p>{{person.schoolName || person.agencyName}}</p></div></div><div class="person-actions"><button class="primary" @click="message"><MessageSquare :size="16"/>Message</button><button v-if="person.email" @click="emit('compose-email',{to:person.email})"><Mail :size="16"/>{{person.email}}</button><a v-if="phone.telHref" :href="phone.telHref"><Phone :size="16"/>{{phone.display}}</a></div><p v-if="person.bio" class="bio">{{person.bio}}</p><section v-for="group in person.focus || []" :key="group.label" class="focus-group"><h4>{{group.label}}</h4><ul><li v-for="value in group.values" :key="value">{{value}}</li></ul></section></template></section></div></Teleport></template>
<style scoped>
.person-profile-overlay{position:fixed;inset:0;z-index:2900;background:#17345177;display:grid;place-items:center;padding:16px;color:#203b5b;font:14px/1.5 system-ui;box-sizing:border-box}.person-profile-overlay>section{background:#fff;width:100%;max-width:600px;max-height:85dvh;overflow:auto;border-radius:18px;padding:20px;box-sizing:border-box;min-width:0}.person-profile-overlay header{display:flex;align-items:center;justify-content:space-between;gap:8px}.person-profile-overlay h2{font-size:17px;margin:0}.person-profile-overlay button,.person-actions a{font:inherit;border:1px solid #d8e2f1;border-radius:10px;background:#f4f7fd;color:#2b527d;padding:10px;min-height:42px;display:inline-flex;align-items:center;justify-content:center;gap:6px;cursor:pointer;text-decoration:none;-webkit-user-select:none;user-select:none}.person-heading{display:flex;gap:14px;align-items:center;margin:23px 0}.person-heading>div{min-width:0}.person-heading h3{display:flex;flex-wrap:wrap;column-gap:.35em;row-gap:0;margin:0;font-size:19px;overflow-wrap:anywhere}.credential{font-size:15px}.person-heading p{margin:5px 0;color:#6c7f98}.person-heading small{font-size:11px;letter-spacing:.06em}.person-actions{display:flex;gap:8px;flex-wrap:wrap}.person-actions button,.person-actions a{max-width:100%;overflow-wrap:anywhere}.person-actions .primary{color:#fff;background:#245cdb;border-color:#245cdb}.bio{white-space:pre-line}.focus-group h4{margin:18px 0 7px;font-size:13px}.focus-group ul{display:flex;gap:7px;flex-wrap:wrap;list-style:none;padding:0;margin:0}.focus-group li{background:#f0f5fd;border-radius:20px;padding:6px 11px;font-size:12px}:focus-visible{outline:3px solid #80a7ed;outline-offset:2px}
</style>
